<?php
declare(strict_types=1);require_once dirname(__DIR__).'/includes/auth.php';require_once dirname(__DIR__).'/includes/csrf.php';require_once __DIR__.'/layout.php';require_once dirname(__DIR__).'/services/batches.php';$current=tuman_require_role('TEACHER');$db=tuman_database();$id=filter_var($_GET['id']??$_POST['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$id||tuman_teacher_batch($db,$current['id'],(int)$id)===null){http_response_code(404);exit('Batch unavailable.');}$v=['username'=>'','email'=>'','first_name'=>'','last_name'=>'','phone'=>'','country_code'=>''];$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){foreach($v as $k=>$x)$v[$k]=trim((string)($_POST[$k]??''));$v['password']=(string)($_POST['password']??'');try{if(!tuman_csrf_is_valid($_POST['csrf_token']??null))throw new InvalidArgumentException('Your request could not be verified.');$db->beginTransaction();$assignment=tuman_enrol_student($db,$current['id'],$v);tuman_add_batch_member($db,$current['id'],(int)$id,$assignment,gmdate('Y-m-d'));$db->commit();header('Location: /Tuman/teacher/batch-view.php?id='.$id);exit;}catch(InvalidArgumentException $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log($e->getMessage());$error='Unable to enrol the student right now.';}}tuman_teacher_page_start('Enrol batch student');
?>
<h1>Enrol new student into batch</h1><?php if($error):?><p role="alert"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></p><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(tuman_csrf_token(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="id" value="<?=(int)$id?>"><p><label>First name <input name="first_name" required value="<?=htmlspecialchars($v['first_name'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>Last name <input name="last_name" value="<?=htmlspecialchars($v['last_name'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>Username <input name="username" required value="<?=htmlspecialchars($v['username'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>Temporary password <input type="password" name="password" minlength="12" required></label></p><p><label>Email <input type="email" name="email" value="<?=htmlspecialchars($v['email'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>Phone <input name="phone" value="<?=htmlspecialchars($v['phone'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>Country <select name="country_code"><option value="">Not specified</option><?php foreach(TUMAN_COUNTRIES as $code=>$name):?><option value="<?=$code?>"<?=$v['country_code']===$code?' selected':''?>><?=htmlspecialchars($name,ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label></p><p><button>Enrol into batch</button> <a href="/Tuman/teacher/batch-view.php?id=<?=(int)$id?>">Cancel</a></p></form><?php tuman_teacher_page_end();
